pub(crate) fn read_memory_control_at(path: &Path) -> Option<crate::memory::MemoryControl> {
    let raw = std::fs::read_to_string(path).ok()?;
    // 只 pluck memoryControl 一个字段，跳过 BotConfig 其余字段（key slots / MCP / evolution ...）
    // 的反序列化开销。gate 路径每轮聊天 + 每次模型记忆工具调用都会走，全表 parse 是浪费。
    let val: serde_json::Value = serde_json::from_str(&raw).ok()?;
    val.get("memoryControl")
        .and_then(|v| serde_json::from_value(v.clone()).ok())
}

